// Program.cs
builder.Services.AddAuthentication(options =>
{
    options.DefaultScheme = CookieAuthenticationDefaults.AuthenticationScheme;
    options.DefaultChallengeScheme = Saml2Defaults.Scheme;
})
.AddCookie()
.AddSaml2(options =>
{
    options.SPOptions.EntityId = new EntityId("https://app.example.com");

    options.SPOptions.ReturnUrl = new Uri("https://app.example.com/");

    var identityProvider = new IdentityProvider(
        new EntityId("https://idp.example.com"), 
        options.SPOptions)
    {
        LoadMetadata = true,
        MetadataLocation = "https://idp.example.com/metadata"
    };

    options.IdentityProviders.Add(identityProvider);

    options.SPOptions.ServiceCertificates.Add(
        new X509Certificate2("signing-cert.pfx", "password"));
});
